python3 -c 'import re,sys
d=open('"'"'/home/user/release/reports/deployment_summary.log'"'"').read()
ls=d.splitlines()
pairs=set()
for l in ls:
    m=re.match(r'"'"'service: ([^;]+); env: ([^;]+);'"'"',l)
    if m: pairs.add(m.groups())
svcs={s for s,e in pairs}
ok=d.endswith('"'"'\n'"'"') and len(ls)==6 and len(svcs)==3 and pairs=={(s,e) for s in svcs for e in ('"'"'production'"'"','"'"'staging'"'"')}
sys.exit(0 if ok else 1)'
